def transform(g):
    from collections import Counter
    cnt=Counter(v for r in g for v in r); B=cnt.most_common(1)[0][0]
    h,w=len(g),len(g[0])
    const_rows=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=B]
    const_cols=[j for j in range(w) if len({r[j] for r in g})==1 and g[0][j]!=B]
    sepc={g[i][0] for i in const_rows}|{g[0][j] for j in const_cols}
    def runs(idxs, n):
        out=[];cur=[]
        for i in range(n):
            if i in idxs:
                if cur: out.append(cur); cur=[]
            else: cur.append(i)
        if cur: out.append(cur)
        return out
    rruns=runs(set(const_rows),h); cruns=runs(set(const_cols),w)
    has_pat=lambda cells, horiz: any(g[i][j] not in ({B}|sepc) for i,j in ([(c,0) for c in cells] if horiz else [(0,c) for c in cells]))
    # horizontal: pattern run and neighbors
    def maprun(i, rns, pat, horiz):
        # returns source index within grid for row i (horiz=False) using pattern run
        for rn in rns:
            if rn==pat: 
                if i in rn: return i
            else:
                # adjacent run across a separator: align by distance from separator
                if rn[0]>pat[-1]:  # after
                    d=i-rn[0]
                    if 0<=d<len(rn): return pat[0]+d
                elif rn[-1]<pat[0]:  # before
                    d=rn[-1]-i
                    if 0<=d<len(rn): return pat[-1]-d
        return None
    pr_r=[rn for rn in rruns if any(any(g[i][j] not in ({B}|sepc) for j in range(w)) for i in rn)]
    pr_c=[rn for rn in cruns if any(any(g[i][j] not in ({B}|sepc) for i in range(h)) for j in rn)]
    pr_r=pr_r[0] if pr_r else None; pr_c=pr_c[0] if pr_c else None
    out=[]
    for i in range(h):
        ri = i if (pr_r is None or i in pr_r or not const_rows) else maprun(i,rruns,pr_r,False)
        if i in const_rows: ri='S'
        row=[]
        for j in range(w):
            cj = j if (pr_c is None or j in pr_c or not const_cols) else maprun(j,cruns,pr_c,True)
            if j in const_cols: cj='S'
            if ri=='S': row.append(g[const_rows[0]][0])
            elif cj=='S': row.append(g[0][const_cols[0]])
            else: row.append(g[ri][cj])
        out.append(row)
    return out
