lib='''def background(grid):
    """The most common color in the grid."""
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def constant_lines(grid, axis):
    """Indices of full rows (axis=0) or columns (axis=1) that are one single color different from the background."""
    B = background(grid)
    if axis == 0:
        return [i for i, row in enumerate(grid) if len(set(row)) == 1 and row[0] != B]
    return [j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1 and grid[0][j] != B]

def runs_between(idxs, n):
    """Maximal runs of indices in range(n) that are not in idxs, each a sorted list."""
    out, cur = [], []
    for i in range(n):
        if i in idxs:
            if cur: out.append(cur); cur = []
        else:
            cur.append(i)
    if cur: out.append(cur)
    return out

def pattern_run(grid, rns, axis):
    """The run (from runs_between over separator lines) whose cells hold colors other than background and separators."""
    B = background(grid)
    sepc = set()
    if axis == 0:
        for i in constant_lines(grid, 0): sepc.add(grid[i][0])
        for j in constant_lines(grid, 1): sepc.add(grid[0][j])
        for rn in rns:
            if any(grid[i][j] not in ({B} | sepc) for i in rn for j in range(len(grid[0]))):
                return rn
    return None

def tile_from_pattern(grid):
    """Fill every block between separator lines with an aligned copy of the block holding the pattern, separators included."""
    B = background(grid)
    h, w = len(grid), len(grid[0])
